import { checkExport, type ExportControl } from "./export-control";
import type { AssetStore } from "../core/assets";
import type { DocumentData } from "../core/model";
import type { DocumentRenderer } from "./renderer";

const crcTable = Uint32Array.from({ length: 256 }, (_, index) => {
  let value = index;
  for (let bit = 0; bit < 8; bit++)
    value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
  return value >>> 0;
});
function chunk(type: string, bytes: Uint8Array): Uint8Array<ArrayBuffer> {
  const result = new Uint8Array(bytes.length + 12);
  const view = new DataView(result.buffer);
  view.setUint32(0, bytes.length);
  result.set(new TextEncoder().encode(type), 4);
  result.set(bytes, 8);
  let crc = 0xffffffff;
  for (let i = 4; i < result.length - 4; i++)
    crc = crcTable[(crc ^ result[i]) & 255] ^ (crc >>> 8);
  view.setUint32(result.length - 4, (crc ^ 0xffffffff) >>> 0);
  return result;
}

/** Native scanline sink; retains compressed output and one bounded caller strip. */
export class PngRowEncoder {
  private parts:BlobPart[]=[];
  private compression=new CompressionStream('deflate');
  private writer=this.compression.writable.getWriter();
  private reader=this.compression.readable.getReader();
  private collecting:Promise<void>;
  private rows=0;
  constructor(readonly width:number,readonly height:number){
    if(!Number.isSafeInteger(width)||!Number.isSafeInteger(height)||width<1||height<1||width>0x7fffffff||height>0x7fffffff)throw new Error('Invalid PNG geometry.');
    const header=new Uint8Array(13),view=new DataView(header.buffer);view.setUint32(0,width);view.setUint32(4,height);header[8]=8;header[9]=6;
    this.parts=[new Uint8Array([137,80,78,71,13,10,26,10]),chunk('IHDR',header),chunk('sRGB',new Uint8Array([0]))];
    this.collecting=(async()=>{while(true){const {value,done}=await this.reader.read();if(done)break;this.parts.push(chunk('IDAT',value));}})();void this.collecting.catch(()=>{});
  }
  async append(rgba:Uint8Array,rows:number):Promise<void>{
    if(!Number.isInteger(rows)||rows<1||this.rows+rows>this.height||rgba.length!==this.width*rows*4)throw new Error('PNG scanlines do not match source geometry.');
    const bytes=this.width*4,filtered=new Uint8Array((bytes+1)*rows);
    for(let y=0;y<rows;y++)filtered.set(rgba.subarray(y*bytes,(y+1)*bytes),y*(bytes+1)+1);
    await this.writer.write(filtered);this.rows+=rows;
  }
  async finish():Promise<Blob>{
    if(this.rows!==this.height)throw new Error('Incomplete PNG scanlines.');
    await this.writer.close();await this.collecting;this.parts.push(chunk('IEND',new Uint8Array()));return new Blob(this.parts,{type:'image/png'});
  }
  async abort(reason:unknown){await Promise.allSettled([this.writer.abort(reason),this.reader.cancel(reason)]);}
}

/** PNG is streamed through a deflater, without a document-sized canvas or RGBA
 * buffer. Retained output is compressed; source decoding remains browser-managed.
 */
export async function exportPng(
  document: DocumentData,
  assets: AssetStore,
  renderer: DocumentRenderer,
  control?: ExportControl,
): Promise<Blob> {
  checkExport(control);
  control?.onProgress?.({phase:"rendering",fraction:0});
  const { width, height } = document;
  // This is the PNG format's dimension boundary, not an image import restriction.
  if (width > 0x7fffffff || height > 0x7fffffff)
    throw new Error("These dimensions exceed the PNG file format.");
  const header = new Uint8Array(13);
  const view = new DataView(header.buffer);
  view.setUint32(0, width);
  view.setUint32(4, height);
  header[8] = 8;
  header[9] = 6;
  const parts: BlobPart[] = [
    new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", header),
    chunk("sRGB", new Uint8Array([0])),
  ];
  const compression = new CompressionStream("deflate");
  const writer = compression.writable.getWriter();
  const reader = compression.readable.getReader();
  const collect = (async () => {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      parts.push(chunk("IDAT", value));
    }
  })();
  // Attach rejection handling before the first await in the producer.
  void collect.catch(() => {});
  try {
    const rowBytes = width * 4 + 1;
    const rowsPerStrip = Math.max(
      1,
      Math.min(64, Math.floor(4_000_000 / rowBytes)),
    );
    for (let y = 0; y < height; y += rowsPerStrip) {
      checkExport(control);
      const rows = Math.min(rowsPerStrip, height - y);
      const strip = new Uint8Array(rowBytes * rows); // filter byte 0 for each row
      for (let x = 0; x < width; x += 2048) {
        const tileWidth = Math.min(2048, width - x);
        const tile = await renderer.render(document, assets, {
          region: { x, y, width: tileWidth, height: rows },
          cache: false,
          readback: true,
        });
        try {
          checkExport(control);
          const pixels = tile
            .getContext("2d")!
            .getImageData(0, 0, tileWidth, rows).data;
          for (let row = 0; row < rows; row++)
            strip.set(
              pixels.subarray(row * tileWidth * 4, (row + 1) * tileWidth * 4),
              row * rowBytes + 1 + x * 4,
            );
        } finally {
          tile.width = tile.height = 0;
        }
      }
      await writer.write(strip);
      control?.onProgress?.({phase:"rendering",fraction:(y+rows)/height});
      // Let input, status messages, and cancellation by navigation proceed.
      await new Promise<void>((resolve) => setTimeout(resolve, 0));
    }
    checkExport(control);
    control?.onProgress?.({phase:"encoding",fraction:null});
    await writer.close();
    await collect;
    checkExport(control);
  } catch (error) {
    await writer.abort(error).catch(() => {});
    await reader.cancel().catch(() => {});
    throw error;
  }
  parts.push(chunk("IEND", new Uint8Array()));
  return new Blob(parts, { type: "image/png" });
}

/**
 * Encodes an uncompressed RGBA pixel buffer directly into a compressed PNG Blob.
 */
export async function encodeRgbaPng(
  rgba: Uint8Array,
  width: number,
  height: number,
): Promise<Blob> {
  if (width > 0x7fffffff || height > 0x7fffffff)
    throw new Error("These dimensions exceed the PNG file format.");
  const header = new Uint8Array(13);
  const view = new DataView(header.buffer);
  view.setUint32(0, width);
  view.setUint32(4, height);
  header[8] = 8; // bit depth
  header[9] = 6; // color type RGBA

  const parts: BlobPart[] = [
    new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", header),
    chunk("sRGB", new Uint8Array([0])),
  ];

  const rowBytes = width * 4 + 1;
  const filtered = new Uint8Array(rowBytes * height);
  for (let y = 0; y < height; y++) {
    filtered[y * rowBytes] = 0; // Filter: None
    filtered.set(
      rgba.subarray(y * width * 4, (y + 1) * width * 4),
      y * rowBytes + 1,
    );
  }

  const compression = new CompressionStream("deflate");
  const writer = compression.writable.getWriter();
  const reader = compression.readable.getReader();
  const collect = (async () => {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      parts.push(chunk("IDAT", value));
    }
  })();
  void collect.catch(() => {});

  try {
    await writer.write(filtered);
    await writer.close();
    await collect;
  } catch (error) {
    await writer.abort(error).catch(() => {});
    await reader.cancel().catch(() => {});
    throw error;
  }

  parts.push(chunk("IEND", new Uint8Array()));
  return new Blob(parts, { type: "image/png" });
}


/** Worker-side native encoding of canvas-captured RGBA; direct PNG fallback. */
export async function encodeCapturedPng(pixels: Uint8ClampedArray, width: number, height: number): Promise<Blob> {
  if (!Number.isSafeInteger(width) || !Number.isSafeInteger(height) || width <= 0 || height <= 0 || pixels.length !== width * height * 4)
    throw new Error("PNG encoding requires matching RGBA dimensions.");
  let png: Blob | undefined;
  if (typeof OffscreenCanvas !== "undefined") {
    const canvas = new OffscreenCanvas(width, height);
    try {
      canvas.getContext("2d")!.putImageData(new ImageData(new Uint8ClampedArray(pixels), width, height), 0, 0);
      png = await canvas.convertToBlob({ type: "image/png" });
    } catch { /* Native encoding is optional; retain the direct encoder. */ }
    finally { canvas.width = canvas.height = 1; }
  }
  png ??= await encodeRgbaPng(new Uint8Array(pixels.buffer, pixels.byteOffset, pixels.byteLength), width, height);
  return png;
}

